import {
  BrainCircuit,
  Code2,
  Dna,
  FileText,
  Image as ImageIcon,
  Layout,
  Library,
  type LucideIcon,
  Music,
  Palette,
  Shapes,
  Sparkles,
  Terminal,
  Video,
} from "lucide-react";
import { Complex } from "./HyperbolicMath";

export type NodeType = "root" | "area" | "project" | "note" | "media";

export interface GraphNode {
  icon?: LucideIcon;
  id: string;
  label: string;
  logicalPos: Complex;
  type: NodeType;
}

export interface GraphEdge {
  sourceId: string;
  targetId: string;
}

const ICONS = [
  Code2,
  FileText,
  ImageIcon,
  Music,
  Video,
  Terminal,
  Palette,
  Layout,
  Shapes,
  Dna,
  Library,
  Sparkles,
];

/**
 * Procedural Tree Generation in Hyperbolic Space
 * In hyperbolic space, circumference grows exponentially.
 * We can fit a regular tree where every node has K children, effectively forever.
 */
export const generateHyperbolicTree = (): {
  nodes: GraphNode[];
  edges: GraphEdge[];
} => {
  const nodes: GraphNode[] = [];
  const edges: GraphEdge[] = [];

  // Root at origin
  const root: GraphNode = {
    id: "root",
    logicalPos: new Complex(0, 0),
    label: "My Second Brain",
    type: "root",
    icon: BrainCircuit,
  };
  nodes.push(root);

  // BFS Queue
  const queue: {
    parent: GraphNode;
    level: number;
    angleStart: number;
    angleEnd: number;
  }[] = [];
  queue.push({ parent: root, level: 0, angleStart: 0, angleEnd: 2 * Math.PI });

  let nodeCount = 1;

  // Radial layout layers (Poincare radius)
  // Pack tighter near center, spacing out towards edge
  // Optimized for 3-4 layers: spread them out a bit more to breathe
  const radii = [0, 0.4, 0.7, 0.88, 0.95];

  while (queue.length > 0) {
    const { parent, level, angleStart, angleEnd } = queue.shift()!;
    if (level >= 3) {
      continue; // Max depth 3 (Root + 3 layers = 4 layers total)
    }

    const r = radii[level + 1];

    // Organic branching factor based on level
    // Reduced for cleaner demo
    let minB = 2,
      maxB = 3;
    if (level === 0) {
      minB = 3;
      maxB = 4;
    } // Areas (fewer)
    if (level === 1) {
      minB = 2;
      maxB = 3;
    } // Projects (fewer)
    if (level === 2) {
      minB = 1;
      maxB = 2;
    } // Notes (very few leaf nodes)

    const count = Math.floor(Math.random() * (maxB - minB + 1)) + minB;

    // Adding randomness to angle spans
    const totalSpan = angleEnd - angleStart;
    const angleStep = totalSpan / count;

    for (let i = 0; i < count; i++) {
      const theta = angleStart + angleStep * i + angleStep / 2;

      // Jitter: +/- 20% of the step
      const jitter = (Math.random() - 0.5) * angleStep * 0.4;
      const finalTheta = theta + jitter;

      // Helper to randomly pick icon
      const RandomIcon = ICONS[Math.floor(Math.random() * ICONS.length)];

      let type: NodeType = "note";
      let label = `Note ${nodeCount}`;
      if (level === 0) {
        type = "area";
        label =
          ["Dev", "Writing", "Health", "Art", "Finance", "Travel"][i % 6] ||
          "Area";
      } else if (level === 1) {
        type = "project";
        label = `Project ${String.fromCharCode(65 + i)}`;
      } else if (Math.random() > 0.8) {
        type = "media";
        label = "Attachment";
      }

      const pos = new Complex(
        r * Math.cos(finalTheta),
        r * Math.sin(finalTheta)
      );
      const id = `node-${nodeCount++}`;

      const newNode: GraphNode = {
        id,
        logicalPos: pos,
        label,
        type,
        icon: level < 3 ? RandomIcon : undefined,
      };

      nodes.push(newNode);
      edges.push({ sourceId: parent.id, targetId: newNode.id });

      queue.push({
        parent: newNode,
        level: level + 1,
        angleStart: angleStart + angleStep * i,
        angleEnd: angleStart + angleStep * (i + 1),
      });
    }
  }

  return { nodes, edges };
};

export class Complex {
  constructor(
    public re: number,
    public im: number
  ) {}

  static from(re: number, im = 0) {
    return new Complex(re, im);
  }

  add(other: Complex): Complex {
    return new Complex(this.re + other.re, this.im + other.im);
  }

  sub(other: Complex): Complex {
    return new Complex(this.re - other.re, this.im - other.im);
  }

  mul(other: Complex): Complex {
    return new Complex(
      this.re * other.re - this.im * other.im,
      this.re * other.im + this.im * other.re
    );
  }

  div(other: Complex): Complex {
    const denom = other.re * other.re + other.im * other.im;
    if (denom === 0) {
      throw new Error("Division by zero");
    }
    return new Complex(
      (this.re * other.re + this.im * other.im) / denom,
      (this.im * other.re - this.re * other.im) / denom
    );
  }

  conj(): Complex {
    return new Complex(this.re, -this.im);
  }

  abs(): number {
    return Math.sqrt(this.re * this.re + this.im * this.im);
  }

  // Returns arguments between -pi and pi
  arg(): number {
    return Math.atan2(this.im, this.re);
  }
}

/**
 * Applies a Möbius transformation to a point z on the Poincaré disk.
 * transformation: z -> (z - a) / (1 - conj(a) * z)
 * This maps 'a' to the origin (0,0).
 * 'a' conceptually represents the "center" of the view in Poincaré coordinates.
 */
export function mobiusTransform(z: Complex, a: Complex): Complex {
  // Numerator: z - a
  const num = z.sub(a);

  // Denominator: 1 - conj(a) * z
  const aConj = a.conj();
  const prod = aConj.mul(z);
  const one = new Complex(1, 0);
  const den = one.sub(prod);

  return num.div(den);
}

/**
 * Inverse Möbius transformation.
 * effectively mobiusTransform(z, -a) but careful with signs in the denominator logic
 * Actually, the inverse of M_a(z) = (z - a)/(1 - a_bar z) is M_-a(z) = (z + a)/(1 + a_bar z)
 */
export function inverseMobiusTransform(z: Complex, a: Complex): Complex {
  const num = z.add(a);
  const aConj = a.conj();
  const prod = aConj.mul(z);
  const one = new Complex(1, 0);
  const den = one.add(prod);
  return num.div(den);
}

/**
 * Converts screen coordinates (relative to center, normalized to [-1, 1])
 * to a Complex number representing a point on the Poincaré disk.
 */
export function screenToPoincare(x: number, y: number): Complex {
  // Ensure we are within the unit disk
  const dist = Math.sqrt(x * x + y * y);
  if (dist >= 1) {
    // If outside, clamp to edge (or handle as needed, maybe strictly < 1)
    // Using 0.999 to avoid singularity at the boundary
    const angle = Math.atan2(y, x);
    return new Complex(0.999 * Math.cos(angle), 0.999 * Math.sin(angle));
  }
  return new Complex(x, y);
}

/**
 * Converts a Complex number on the Poincaré disk to screen coordinates
 * (relative to center, normalized to [-1, 1]).
 */
export function poincareToScreen(z: Complex): { x: number; y: number } {
  return { x: z.re, y: z.im };
}

/**
 * Calculates the hyperbolic distance between two points on the Poincaré disk.
 * d(a, b) = 2 * tanh^-1( |(a-b)/(1-a_bar*b)| )
 */
export function hyperbolicDistance(a: Complex, b: Complex): number {
  const diff = a.sub(b);
  const aConj = a.conj();
  const denTerm = aConj.mul(b);
  const complexOne = new Complex(1, 0);
  const den = complexOne.sub(denTerm);

  const fraction = diff.div(den);
  const r = Math.min(fraction.abs(), 0.999_999);

  return 2 * Math.atanh(r);
}

/**
 * Generates an SVG path command for the geodesic segment connecting two points
 * in the Poincaré disk model.
 *
 * @param z1 Start point (Complex, unit disk)
 * @param z2 End point (Complex, unit disk)
 * @param r  Viewport radius in pixels (to scale the output)
 * @returns SVG 'd' attribute string (e.g., "M x1 y1 A ...")
 */
export function getGeodesicPath(z1: Complex, z2: Complex, r: number): string {
  const p1x = z1.re * r;
  const p1y = z1.im * r;
  const p2x = z2.re * r;
  const p2y = z2.im * r;

  // Check for collinearity with origin (straight line case)
  // Cross product of vectors z1 and z2.
  // If they are collinear with origin, the geodesic is a straight line.
  const cross = z1.re * z2.im - z1.im * z2.re;

  // Threshold for straight line
  if (Math.abs(cross) < 1e-6) {
    return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} L ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
  }

  // General case: Arc of a circle orthogonal to the unit disk.
  // To find this circle, we use the property that it passes through z1, z2,
  // and the inverse of z1 relative to the unit circle (z1_inv = 1 / conj(z1)).

  const denom = z1.re * z1.re + z1.im * z1.im;
  if (denom < 1e-9) {
    // z1 is origin, straight line to z2
    return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} L ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
  }

  const z1Inv = new Complex(z1.re / denom, -z1.im / denom); // 1/conj(z1)

  // Now find circle passing through z1, z2, z1Inv.
  // Circle equation: |z - c|^2 = R^2
  // This is a standard "Circle from 3 points" problem.
  // Let's use a determinant method or algebraic solver.
  // D = 2(x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2))

  const x1 = z1.re,
    y1 = z1.im;
  const x2 = z2.re,
    y2 = z2.im;
  const x3 = z1Inv.re,
    y3 = z1Inv.im;

  const D = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));

  if (Math.abs(D) < 1e-9) {
    // Points are collinear -> Straight line (should have caught above, but safety fallback)
    return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} L ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
  }

  const N1 = x1 * x1 + y1 * y1;
  const N2 = x2 * x2 + y2 * y2;
  const N3 = x3 * x3 + y3 * y3;

  const cx = (N1 * (y2 - y3) + N2 * (y3 - y1) + N3 * (y1 - y2)) / D;
  const cy = (N1 * (x3 - x2) + N2 * (x1 - x3) + N3 * (x2 - x1)) / D;

  const R_unit = Math.sqrt((cx - x1) ** 2 + (cy - y1) ** 2);

  // Convert circle params to screen space
  const R_screen = R_unit * r;

  // SVG Arc Command: A rx ry x-axis-rotation large-arc-flag sweep-flag x y
  // For orthogonal circles in the Poincaré disk, the center of the defining circle is always
  // outside the unit disk. The arc connecting two points inside the unit disk is unique
  // and relatively short (never > 180 degrees of the orthogonal circle if contained in unit disk).
  // Thus large-arc-flag is 0.
  // sweep-flag '1' works for the standard coordinate system where +y is down,
  // assuming consistent vertex ordering. If needed, a cross-product check can enforce
  // convexity towards the origin, but current visual tests show stability.

  return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} A ${R_screen.toFixed(2)} ${R_screen.toFixed(2)} 0 0 1 ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
}

import React, { useMemo } from "react";
import { Complex, getGeodesicPath, mobiusTransform } from "./HyperbolicMath";

interface HyperbolicGridProps {
  viewCenter: Complex;
  viewportRadius: number;
}

export const HyperbolicGrid = React.memo(function HyperbolicGrid({
  viewCenter,
  viewportRadius,
}: HyperbolicGridProps) {
  // Generate grid lines
  // 1. Radial geodesics (lines passing through origin)
  // In the Poincare disk, lines through the origin are straight lines.
  // However, when the view is transformed, they might curve.
  // A radial line at angle theta is a geodesic from 0 to e^(i*theta).
  // We want to draw these "grid lines" which are fixed in the "World".
  // So we define them in logical space, then transform them by viewCenter.

  const gridPaths = useMemo(() => {
    const paths: string[] = [];
    const step = 0.2; // Spacing for grid lines along the axes
    const limit = 0.95; // Don't go too close to edge

    // Helper to generate a geodesic arc orthogonal to an axis (Real or Imaginary)
    // For the Real axis (horizontal diameter), lines orthogonal to it are "vertical coordinate lines".
    // For a point x0 on Real axis, the geodesic orthogonal to Real axis at x0 is a circle.
    // Center C is on Real axis. Orthogonal to unit disk. Passes through x0.
    // C = (x0^2 + 1) / (2*x0). R = sqrt(C^2 - 1).

    // We generate lines for x0 in (-1, 1).
    // Exceptions: x0=0 -> The imaginary axis (straight line).

    const generateOrthogonalArcs = (isVerticalGrid: boolean) => {
      for (let t = -limit; t <= limit; t += step) {
        if (Math.abs(t) < 0.01) {
          // Central line (Axis itself)
          // If isVerticalGrid (lines cutting X axis), central one is the Y axis (Imaginary axis).
          // Start (0, -1) to (0, 1).
          // If isHorizontalGrid (lines cutting Y axis), central one is X axis.
          // Start (-1, 0) to (1, 0).

          const start = isVerticalGrid
            ? new Complex(0, -0.999)
            : new Complex(-0.999, 0);
          const end = isVerticalGrid
            ? new Complex(0, 0.999)
            : new Complex(0.999, 0);

          const vStart = mobiusTransform(start, viewCenter);
          const vEnd = mobiusTransform(end, viewCenter);
          paths.push(getGeodesicPath(vStart, vEnd, viewportRadius));
          continue;
        }

        // General case: Circular arc
        // For vertical grid: intersects X axis at t. Center on X axis.
        // For horizontal grid: intersects Y axis at t. Center on Y axis.

        const val = t;
        const C_scalar = (val * val + 1) / (2 * val);

        // Construct the circle in Logical Space.
        // We need to sample it or find start/end points on the boundary to use getGeodesicPath?
        // getGeodesicPath connects two points inside the disk.
        // The grid line goes from boundary to boundary.
        // Intersection of Circle(C, R) with Unit circle?
        // Two points: z1, z2.
        // Since circle is orthogonal to unit disk, they intersect at 90 deg.

        // Let's find intersection points of Circle (x-C)^2 + y^2 = R^2 and x^2 + y^2 = 1.
        // (x-C)^2 + 1 - x^2 = R^2 => x^2 - 2xC + C^2 + 1 - x^2 = R^2
        // -2xC + C^2 + 1 = R^2
        // 2xC = C^2 + 1 - R^2.
        // Since R^2 = C^2 - 1, then R^2 - C^2 = -1.
        // 2xC = 1 - (-1) = 2 => xC = 1 => x = 1/C.
        // So the intersection x-coord is 1/C.
        // y = +/- sqrt(1 - x^2).

        const intersectX = 1 / C_scalar;
        const intersectY = Math.sqrt(Math.max(0, 1 - intersectX * intersectX));

        let p1, p2;
        if (isVerticalGrid) {
          // Centers on X axis. Intersections have calc coordinates.
          p1 = new Complex(intersectX, intersectY);
          p2 = new Complex(intersectX, -intersectY);
        } else {
          // Centers on Y axis. Swap X/Y.
          // Circle is x^2 + (y-C)^2 = R^2.
          // Intersection y = 1/C.
          // x = +/- sqrt(1 - y^2).
          p1 = new Complex(intersectY, intersectX); // swap x/y for result
          p2 = new Complex(-intersectY, intersectX);
        }

        // Scale down slightly to 0.999 to hold numerical stability in transform
        p1 = p1.mul(new Complex(0.999, 0));
        p2 = p2.mul(new Complex(0.999, 0));

        const vStart = mobiusTransform(p1, viewCenter);
        const vEnd = mobiusTransform(p2, viewCenter);

        paths.push(getGeodesicPath(vStart, vEnd, viewportRadius));
      }
    };

    // 1. Vertical Grid Lines (Orthogonal to Real Axis)
    generateOrthogonalArcs(true);

    // 2. Horizontal Grid Lines (Orthogonal to Imaginary Axis)
    generateOrthogonalArcs(false);

    return { lines: paths, circles: [] }; // No circles array needed for this style
  }, [viewCenter, viewportRadius]);

  return (
    <g className="fade-in-grid pointer-events-none">
      {gridPaths.lines.map((d, i) => (
        <path
          d={d}
          fill="none"
          key={`l-${i}`}
          stroke="rgba(255,255,255,0.03)"
          strokeWidth="1"
        />
      ))}
      {gridPaths.circles}
    </g>
  );
});

import { X } from "lucide-react";
import React from "react";

interface HyperbolicInfoModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export function HyperbolicInfoModal({
  isOpen,
  onClose,
}: HyperbolicInfoModalProps) {
  const [isHoveringEscher, setIsHoveringEscher] = React.useState(false);
  const [mousePosition, setMousePosition] = React.useState({ x: 0, y: 0 });
  const [smoothPosition, setSmoothPosition] = React.useState({ x: 0, y: 0 });

  React.useEffect(() => {
    const lerp = (start: number, end: number, factor: number) => {
      return start + (end - start) * factor;
    };

    let animationFrameId: number;

    const animate = () => {
      setSmoothPosition((prev) => ({
        x: lerp(prev.x, mousePosition.x, 0.15),
        y: lerp(prev.y, mousePosition.y, 0.15),
      }));
      animationFrameId = requestAnimationFrame(animate);
    };

    if (isHoveringEscher) {
      animate();
    }

    return () => {
      if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
      }
    };
  }, [mousePosition, isHoveringEscher]);

  const handleMouseMove = (e: React.MouseEvent) => {
    setMousePosition({ x: e.clientX, y: e.clientY });
  };

  if (!isOpen) {
    return null;
  }

  return (
    <div className="fade-in absolute inset-0 z-100 flex animate-in items-center justify-center bg-black/60 p-4 backdrop-blur-xs duration-200">
      {/* Escher Hover Preview - Hidden on mobile */}
      <div
        className="pointer-events-none fixed z-110 hidden overflow-hidden rounded-lg border border-white/10 bg-black/80 shadow-2xl backdrop-blur-xl transition-opacity duration-300 sm:block"
        style={{
          left: 0,
          top: 0,
          transform: `translate3d(${smoothPosition.x + 20}px, ${smoothPosition.y + 20}px, 0)`,
          opacity: isHoveringEscher ? 1 : 0,
          width: "280px",
          height: "280px",
        }}
      >
        <div className="relative h-full w-full">
          <img
            alt="M.C. Escher Circle Limit"
            className="h-full w-full object-contain p-2"
            src="https://www.razisyed.cv/experiments/non-euclidean-hyperbolic-workspace/escher.png"
          />
          <div className="pointer-events-none absolute inset-0 bg-linear-to-t from-black/20 to-transparent" />
        </div>
      </div>

      <div className="relative mx-4 flex max-h-[90%] w-full max-w-lg flex-col overflow-hidden rounded-2xl border border-white/10 bg-zinc-950/90 shadow-2xl">
        {/* Header: Title + Close Button */}
        <div className="relative flex-none border-white/5 border-b p-6 pb-4">
          <button
            className="absolute top-4 right-4 rounded-full p-2 text-white/50 transition-colors hover:bg-white/10 hover:text-white"
            onClick={onClose}
          >
            <X size={20} />
          </button>
          <div>
            <h2 className="mb-2 pr-8 font-bold text-white text-xl sm:text-2xl">
              Non-Euclidean Hyperbolic Workspace
            </h2>
            <div className="h-0.5 w-12 rounded-full bg-sky-500/50" />
          </div>
        </div>

        {/* Scrollable Content */}
        <div className="custom-scrollbar flex-1 space-y-6 overflow-y-auto p-6 pt-4 text-zinc-300">
          <div className="space-y-4 text-sm leading-relaxed">
            <section>
              <h3 className="mb-1 font-medium text-sky-400">Concept</h3>
              <p>
                This experiment abandons the standard Euclidean plane of the web
                browser for <strong>Hyperbolic Geometry</strong>, specifically
                utilizing the <strong>Poincaré Disk Model</strong>—the same
                geometry made famous by{" "}
                <span
                  className="inline-block cursor-help border-sky-300/30 border-b text-sky-300 transition-colors hover:border-sky-300"
                  onMouseEnter={() => setIsHoveringEscher(true)}
                  onMouseLeave={() => setIsHoveringEscher(false)}
                  onMouseMove={handleMouseMove}
                >
                  M.C. Escher&apos;s <em>Circle Limit</em> woodcuts
                </span>
                . In this non-Euclidean space, the entire infinite plane is
                mapped onto a finite unit circle.
              </p>
            </section>

            <section>
              <h3 className="mb-1 font-medium text-purple-400">The Math</h3>
              <ul className="list-disc space-y-1 pl-4 text-zinc-400">
                <li>
                  <strong>Poincaré Disk</strong>: A model of hyperbolic geometry
                  where &quot;lines&quot; are circular arcs orthogonal to the
                  boundary circle.
                </li>
                <li>
                  <strong>Möbius Transformations</strong>: Navigation is not
                  simple addition (
                  <span className="font-mono text-zinc-300">x + Δx</span>); it
                  is a complex conformal mapping (
                  <span className="font-mono text-zinc-300">
                    z ↦ (z - a)/(1 - āz)
                  </span>
                  ) that preserves angles but distorts distances.
                </li>
                <li>
                  <strong>Exponential Growth</strong>: The circumference of a
                  halo around a point grows exponentially with radius, allowing
                  for infinite information density at the &quot;horizon&quot;
                  (the edge of the circle).
                </li>
              </ul>
            </section>

            <section>
              <h3 className="mb-1 font-medium text-emerald-400">Interaction</h3>
              <ul className="list-disc space-y-1 pl-4 text-zinc-400">
                <li>
                  <strong>Panning</strong>: Dragging the workspace applies a
                  Möbius transformation to the world, bringing distant (tiny)
                  objects to the center (large) and pushing central objects to
                  the periphery.
                </li>
                <li>
                  <strong>The Horizon</strong>: Items never leave the screen;
                  they simply tessellate and shrink towards the boundary circle,
                  which represents infinity.
                </li>
              </ul>
            </section>

            <div className="rounded-lg border border-white/5 bg-white/5 p-3 text-xs">
              <strong className="mb-1 block text-zinc-200">Controls</strong>
              <div className="grid grid-cols-2 gap-2">
                <span>🖱 Mouse Drag</span>
                <span className="text-zinc-500">
                  Pan the view (apply Möbius transformation)
                </span>
                <span>⌨️ Arrow Keys</span>
                <span className="text-zinc-500">Pan the view</span>
                <span>👆 Click Tile</span>
                <span className="text-zinc-500">
                  (Placeholder) Interaction with nodes
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useMemo } from "react";
import {
  type Complex,
  getGeodesicPath,
  mobiusTransform,
} from "./HyperbolicMath";

interface HyperbolicLinkProps {
  end: Complex;
  start: Complex;
  viewCenter: Complex;
  viewportRadius: number;
}

export const HyperbolicLink = React.memo(function HyperbolicLink({
  start,
  end,
  viewCenter,
  viewportRadius,
}: HyperbolicLinkProps) {
  // 1. Transform logical coordinates to visual coordinates based on current view
  // ViewCenter -> Origin
  const vStart = useMemo(
    () => mobiusTransform(start, viewCenter),
    [start, viewCenter]
  );
  const vEnd = useMemo(
    () => mobiusTransform(end, viewCenter),
    [end, viewCenter]
  );

  // 2. Generate SVG Path for the geodesic
  // We pass the viewport radius so the path string has pixel coordinates
  const pathD = useMemo(() => {
    return getGeodesicPath(vStart, vEnd, viewportRadius);
  }, [vStart, vEnd, viewportRadius]);

  return (
    <path
      d={pathD}
      fill="none"
      opacity="0.6"
      pointerEvents="none"
      stroke="url(#link-gradient)"
      strokeWidth="1.5"
      style={{ filter: "url(#glow)" }}
    />
  );
});

import React, { useMemo } from "react";
import { cn } from "@/lib/utils";
import {
  type Complex,
  mobiusTransform,
  poincareToScreen,
} from "./HyperbolicMath";

// Constants for visual logic
const TILE_BASE_SIZE = 100; // base size in pixels at the center

interface HyperbolicTileProps {
  /** Optional content/label */
  children?: React.ReactNode;
  className?: string;
  /** The logical center of this tile in the Poincaré disk (before any view panning) */
  logicalPosition: Complex;
  onClick?: () => void;
  /** The current "view" center (the point in the Poincaré disk that is currently at the screen center) */
  viewCenter: Complex;
  /** Radius of the viewport in pixels, used for converting unit coords to screen pixels */
  viewportRadius: number;
}

export function HyperbolicTile({
  logicalPosition,
  viewCenter,
  viewportRadius,
  children,
  className,
  onClick,
}: HyperbolicTileProps) {
  // 1. Apply the view transformation: move 'viewCenter' to origin
  // The transformation M(z) = (z - a) / (1 - conj(a)*z) maps 'a' to 0.
  const visualPositionComplex = useMemo(() => {
    return mobiusTransform(logicalPosition, viewCenter);
  }, [logicalPosition, viewCenter]);

  // 2. Convert to screen coordinates (unit disk [-1, 1])
  const { x: unitX, y: unitY } = poincareToScreen(visualPositionComplex);

  // 3. Calculate distance from center to determine scale
  // In the Poincaré disk, Euclidean size shrinks as we get closer to the edge.
  // A simple approximation is scaling by (1 - r^2) or similar metric,
  // but strictly speaking, we want conformal scaling.
  // The derivative of the Möbius transform gives the local scaling factor.
  // |M'(z)| = (1 - |a|^2) / |1 - conj(a)z|^2
  // However, for "visual shrinking" towards the edge of the disk (which represents infinity),
  // we can use a scaling factor proportional to the Euclidean metric distortion:
  // scale ~ 1 - r^2  (at r=0 scale=1, at r=1 scale=0)
  const rSquared = unitX * unitX + unitY * unitY;
  const scale = Math.max(0, 1 - rSquared);

  // If tile is too small, don't render it to save performance/visual noise
  if (scale < 0.05) {
    return null;
  }

  // 4. Map unit coordinates to pixel coordinates relative to container center
  const pixelX = unitX * viewportRadius;
  const pixelY = unitY * viewportRadius;

  return (
    <div
      aria-label={`Navigate to ${typeof children === "string" ? children : "node"}`}
      className={cn(
        "absolute flex cursor-pointer select-none items-center justify-center rounded-xl transition-all duration-300 ease-out",
        // Remove default strong gradient, rely on passed className for coloring
        "font-bold text-white",
        "hover:z-50 hover:scale-110 hover:brightness-125",
        className
      )}
      onClick={onClick}
      role="button"
      style={{
        width: `${TILE_BASE_SIZE}px`,
        height: `${TILE_BASE_SIZE}px`,
        willChange: "transform",
        // Use fixed precision to avoid hydration mismatches between server (node) and client (browser) floating point stringification
        transform: `translate3d(${pixelX.toFixed(4)}px, ${pixelY.toFixed(4)}px, 0px) scale(${scale.toFixed(6)})`,
        // Center the element at non-transformed origin so translation works from center
        marginLeft: `-${TILE_BASE_SIZE / 2}px`,
        marginTop: `-${TILE_BASE_SIZE / 2}px`,
        left: "50%",
        top: "50%",
        zIndex: Math.floor(scale * 100), // Larger items on top
      }}
    >
      <div className="overflow-hidden p-2 text-center text-xs">
        {children || "Tile"}
      </div>
    </div>
  );
}

// Optimization: Memoize tile to prevent re-renders if pos/viewCenter are stable (though they change every frame during drag)
export const HyperbolicTileMemo = React.memo(HyperbolicTile);

"use client";
import { Info } from "lucide-react";
import type React from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import {
  type GraphEdge,
  type GraphNode,
  generateHyperbolicTree,
} from "./HyperbolicGraphGen";
import { HyperbolicInfoModal } from "./HyperbolicInfoModal";
import { HyperbolicLink } from "./HyperbolicLink";
import { Complex, mobiusTransform } from "./HyperbolicMath";
import { HyperbolicTileMemo as HyperbolicTile } from "./HyperbolicTile";

export default function NonEuclideanHyperbolicWorkspace() {
  // Hydration fix: Start with empty state to match server, populate purely on client
  const [graph, setGraph] = useState<{
    nodes: GraphNode[];
    edges: GraphEdge[];
  }>({ nodes: [], edges: [] });

  useEffect(() => {
    // Generate the random graph only on the client
    setGraph(generateHyperbolicTree());
  }, []);

  const [viewCenter, setViewCenter] = useState<Complex>(new Complex(0, 0));
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isInfoOpen, setIsInfoOpen] = useState(false);
  const dragStartRef = useRef<{
    screen: { x: number; y: number };
    view: Complex;
  } | null>(null);

  // Responsive Radius State
  const [viewportRadius, setViewportRadius] = useState(300);

  useEffect(() => {
    const updateRadius = () => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setViewportRadius(Math.min(rect.width, rect.height) / 2);
      }
    };

    // Initial measurement
    updateRadius();

    window.addEventListener("resize", updateRadius);
    return () => window.removeEventListener("resize", updateRadius);
  }, []);

  // Keyboard Navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      let dx = 0;
      let dy = 0;
      const step = 0.1; // Amount to move in screen space per key press

      if (e.key === "ArrowLeft") {
        dx = -step;
      }
      if (e.key === "ArrowRight") {
        dx = step;
      }
      if (e.key === "ArrowUp") {
        dy = -step;
      }
      if (e.key === "ArrowDown") {
        dy = step;
      }

      if (dx === 0 && dy === 0) {
        return;
      }

      // Pan logic: Move view center in opposite direction of "camera" move
      // Actually, if I press Right, I expect the camera to move Right, so the world moves Left.
      // World shift = -dx, -dy

      setViewCenter((current) => {
        const shift = new Complex(dx, dy);
        // Note: drag logic used negative shift. Let's test feel.
        // If I press Right (dx>0), I want to see what is to the right.
        // So I move camera right (+x). New center is old center shifted by +x?
        // mobiusTransform(z, a) maps a to 0.
        // If we want new center to be "the point that was at +x", we pass +x as 'a'.
        return mobiusTransform(current, shift);
      });
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  // Reset view removed as per user request

  const getRelCoords = (clientX: number, clientY: number) => {
    if (!containerRef.current) {
      return { x: 0, y: 0, radius: 1 };
    }
    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    const radius = Math.min(rect.width, rect.height) / 2;

    // Normalize to [-1, 1]
    // Note: Coordinate system: +y is Down in DOM, but typically +y is Up in Math.
    // Let's keep DOM coords (+y down) for consistency with mouse,
    // but remember math might expect standard Cartesian.
    // Our Math lib handles arbitrary Complex numbers, so as long as we are consistent it's fine.
    const x = (clientX - centerX) / radius;
    const y = (clientY - centerY) / radius;
    return { x, y, radius };
  };

  const handleStart = useCallback(
    (clientX: number, clientY: number) => {
      setIsDragging(true);
      const { x, y } = getRelCoords(clientX, clientY);
      dragStartRef.current = {
        screen: { x, y },
        view: viewCenter,
      };
    },
    // biome-ignore lint/correctness/useExhaustiveDependencies: legacy experiment, intentional dep pattern
    [viewCenter, getRelCoords]
  ); // viewCenter needed if we want to capture it exactly at start, though ref is better?
  // Actually viewCenter is in state, so closure captures it.
  // Ideally getRelCoords should also be memoized or stable.
  // simpler: just add missing dep to useEffect and suppress if needed, OR memorize functions.

  // Let's go with memoizing handlers to be clean.

  const handleMove = useCallback(
    (clientX: number, clientY: number) => {
      if (!(isDragging && dragStartRef.current)) {
        return;
      }

      const { x, y } = getRelCoords(clientX, clientY);

      // Sensitivity panner
      const dx = x - dragStartRef.current.screen.x;
      const dy = y - dragStartRef.current.screen.y;

      const currentC = dragStartRef.current.view;
      const shift = new Complex(-dx * 0.8, -dy * 0.8);

      const newCenter = mobiusTransform(currentC, shift);
      setViewCenter(newCenter);
    },
    // biome-ignore lint/correctness/useExhaustiveDependencies: legacy experiment, intentional dep pattern
    [isDragging, getRelCoords]
  );

  const handleEnd = useCallback(() => {
    setIsDragging(false);
    dragStartRef.current = null;
  }, []);

  // Mouse Event Handlers
  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) {
      return;
    }
    e.preventDefault();
    handleStart(e.clientX, e.clientY);
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => handleMove(e.clientX, e.clientY);
    const handleMouseUp = () => handleEnd();

    if (isDragging) {
      window.addEventListener("mousemove", handleMouseMove);
      window.addEventListener("mouseup", handleMouseUp);
    }

    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleMouseUp);
    };
  }, [isDragging, handleMove, handleEnd]);

  // Touch Event Handlers
  const handleTouchStart = (e: React.TouchEvent) => {
    const touch = e.touches[0];
    handleStart(touch.clientX, touch.clientY);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    const touch = e.touches[0];
    handleMove(touch.clientX, touch.clientY);
  };

  const handleTouchEnd = () => {
    handleEnd();
  };

  return (
    <div className="relative flex h-full min-h-[400px] w-full touch-none select-none flex-col items-center justify-center overflow-hidden bg-zinc-950 p-4 sm:p-8">
      {/* Controls / Info Button */}
      <div className="absolute top-4 right-4 z-50 sm:top-6 sm:right-6">
        <button
          className="group rounded-full border border-white/5 bg-white/5 p-3 text-white/70 shadow-lg backdrop-blur-md transition-colors hover:bg-white/10 hover:text-white"
          onClick={() => setIsInfoOpen(true)}
          title="About Hyperbolic Workspace"
        >
          <Info
            className="transition-transform group-hover:scale-110"
            size={24}
          />
        </button>
      </div>

      <HyperbolicInfoModal
        isOpen={isInfoOpen}
        onClose={() => setIsInfoOpen(false)}
      />

      {/* Viewport Container */}
      <div
        className={cn(
          "relative aspect-square w-full max-w-[600px] cursor-move touch-none overflow-hidden rounded-full border border-sky-900/30",
          // Added outer glow here so it isn't clipped by overflow-hidden
          "shadow-[0_0_100px_rgba(56,189,248,0.1)]",
          "bg-[radial-gradient(circle_at_center,#1a1b24_0%,#09090b_60%,#000000_100%)]",
          isDragging && "cursor-grabbing"
        )}
        onMouseDown={handleMouseDown}
        onTouchEnd={handleTouchEnd}
        onTouchMove={handleTouchMove}
        onTouchStart={handleTouchStart}
        ref={containerRef}
      >
        {/* SVG Layer for Links */}
        <svg
          className="pointer-events-none absolute inset-0 z-10 h-full w-full"
          viewBox="-300 -300 600 600"
        >
          <defs>
            <linearGradient
              id="link-gradient"
              x1="0%"
              x2="100%"
              y1="0%"
              y2="0%"
            >
              <stop offset="0%" stopColor="rgba(56, 189, 248, 0.1)" />{" "}
              {/* Sky 400 at 10% */}
              <stop offset="100%" stopColor="rgba(168, 85, 247, 0.1)" />{" "}
              {/* Purple 500 at 10% */}
            </linearGradient>
            <filter height="200%" id="glow" width="200%" x="-50%" y="-50%">
              <feGaussianBlur result="coloredBlur" stdDeviation="4" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          <g transform="translate(0, 0)">
            {/* Grid removed as per user request */}

            {graph.edges.map((edge) => {
              const source = graph.nodes.find((n) => n.id === edge.sourceId);
              const target = graph.nodes.find((n) => n.id === edge.targetId);
              if (!(source && target)) {
                return null;
              }

              return (
                <HyperbolicLink
                  end={target.logicalPos}
                  key={`${edge.sourceId}-${edge.targetId}`}
                  start={source.logicalPos}
                  viewCenter={viewCenter}
                  viewportRadius={300} // Keep 300 for SVG coord space
                />
              );
            })}
          </g>
        </svg>

        {/* Tiles Layer */}
        <div className="pointer-events-none absolute inset-0 z-20">
          {/* Center Crosshair - made more subtle */}
          <div className="absolute top-1/2 left-1/2 z-0 h-0.5 w-0.5 rounded-full bg-sky-500/30" />

          {graph.nodes.map((node) => (
            <HyperbolicTile
              className={cn(
                "backdrop-blur-md transition-all duration-300",
                // Base glassmorphism - reduced opacity
                "border border-white/10 bg-white/5 shadow-[0_4px_16px_rgba(0,0,0,0.5)]",
                // Type specific glows AND backgrounds - reduced tint opacity to be subtle
                node.type === "root" &&
                  "border-rose-500/20 bg-rose-500/10 text-rose-100 shadow-[0_0_30px_rgba(244,63,94,0.1)]",
                node.type === "area" &&
                  "border-indigo-500/20 bg-indigo-500/10 text-indigo-100 shadow-[0_0_20px_rgba(99,102,241,0.1)]",
                node.type === "project" &&
                  "border-purple-500/20 bg-purple-500/10 text-purple-100 shadow-[0_0_15px_rgba(168,85,247,0.1)]",
                node.type === "note" &&
                  "border-emerald-500/20 bg-emerald-500/10 text-emerald-100 shadow-[0_0_10px_rgba(16,185,129,0.1)]",
                node.type === "media" &&
                  "border-amber-500/20 bg-amber-500/10 text-amber-100 shadow-[0_0_10px_rgba(245,158,11,0.1)]"
              )}
              key={node.id}
              logicalPosition={node.logicalPos}
              viewCenter={viewCenter} // Use dynamic radius for DOM elements
              viewportRadius={viewportRadius}
            >
              <div className="flex flex-col items-center justify-center gap-1">
                {node.icon && (
                  <node.icon
                    className="opacity-90"
                    size={node.type === "root" ? 32 : 16}
                  />
                )}
                <span
                  className={cn(
                    "text-center font-medium leading-none tracking-tight drop-shadow-md",
                    node.type === "note" && "hidden group-hover:block"
                  )}
                >
                  {node.label}
                </span>
              </div>
            </HyperbolicTile>
          ))}
        </div>

        {/* Horizon Glow Ring - internal shadow only */}
        <div className="pointer-events-none absolute inset-0 z-60 rounded-full border-4 border-sky-500/20 shadow-[inset_0_0_60px_20px_rgba(0,0,0,0.6)]" />
      </div>

      {/* Footer removed */}
    </div>
  );
}
